/**
 * Generate tests for class-based modules
 */
function generateClassTests(className) {
  return `
  
  // ============================================================================
  // CLASS-BASED TESTS
  // ============================================================================

  describe('class methods', () => {
    test('constructor should initialize properly', () => {
      expect(service).toBeInstanceOf(${className});
      expect(service.logger).toBeDefined();
    });

    test('public methods should be callable', () => {
      const methods = Object.getOwnPropertyNames(Object.getPrototypeOf(service));
      const publicMethods = methods.filter(m => 
        m !== 'constructor' && !m.startsWith('_') && typeof service[m] === 'function'
      );
      expect(publicMethods.length).toBeGreaterThan(0);
    });
  });

  describe('instance behavior', () => {
    test('should maintain state between calls', () => {
      expect(service).toBeDefined();
      // Add state tracking tests as needed
    });

    test('should handle errors consistently', async () => {
      try {
        // Call a method that might fail
        await Promise.resolve();
      } catch (error) {
        expect(error).toBeDefined();
      }
    });
  });

  describe('lifecycle', () => {
    test('instance should be reusable', () => {
      expect(service).toBeDefined();
      // Verify instance can be reused for multiple operations
    });

    test('cleanup should work if needed', async () => {
      // If class has cleanup methods, test them
      if (typeof service.cleanup === 'function') {
        await service.cleanup();
      }
      expect(service).toBeDefined();
    });
  });
`;
}

/**
 * Update test file with appropriate template
 */
function refactorTestFile(testFilePath, sourcePath) {
  const sourceCode = fs.readFileSync(sourcePath, 'utf8');
  let testCode = fs.readFileSync(testFilePath, 'utf8');
  
  const pattern = detectExportPattern(sourceCode);
  const filename = path.basename(sourcePath).replace('.js', '');
  const className = filename
    .split('-')
    .map((word, idx) => idx === 0 || word === 'service' || word === 'processor' 
      ? word[0].toUpperCase() + word.slice(1) 
      : word[0].toUpperCase() + word.slice(1))
    .join('');

  let additionalTests = '';

  if (pattern === 'functions-object' || pattern === 'named-exports') {
    const functions = extractExportedFunctions(sourceCode);
    additionalTests = generateFunctionTests(filename, functions);
  } else if (pattern === 'class') {
    additionalTests = generateClassTests(className);
  }

  // Replace or append additional tests
  if (testCode.includes('// TODO: Add specific test cases')) {
    testCode = testCode.replace(
      /\/\/ TODO: Add specific test cases[\s\S]*?}\);/,
      additionalTests
    );
  } else if (!testCode.includes('// FUNCTION-BASED TESTS') && !testCode.includes('// CLASS-BASED TESTS')) {
    // Append before closing describe
    const lastDescribe = testCode.lastIndexOf('});');
    if (lastDescribe !== -1) {
      testCode = testCode.slice(0, lastDescribe) + additionalTests + '\n\n' + testCode.slice(lastDescribe);
    }
  }

  fs.writeFileSync(testFilePath, testCode, 'utf8');
  return { pattern, success: true };
}

/**
 * Main execution
 */
function main() {
  console.log('🔧 Smart Test Refactorer\n');
  console.log('📝 Detecting export patterns and refactoring tests...\n');

  if (!fs.existsSync(TEST_SERVICES_DIR)) {
    console.log('❌ Test services directory not found');
    return;
  }

  const tests = fs.readdirSync(TEST_SERVICES_DIR)
    .filter(f => f.endsWith('.spec.js'));

  let stats = { class: 0, functions: 0, unknown: 0 };

  tests.forEach(testFile => {
    const testPath = path.join(TEST_SERVICES_DIR, testFile);
    const sourceFile = testFile.replace('.spec.js', '.js');
    const sourcePath = path.join(SERVICES_DIR, sourceFile);

    if (!fs.existsSync(sourcePath)) {
      console.log(`⚠️  ${testFile} (source not found)`);
      return;
    }

    try {
      const result = refactorTestFile(testPath, sourcePath);
      stats[result.pattern]++;
      
      const icon = result.pattern === 'class' ? '📦' : result.pattern.includes('function') ? '⚙️' : '❓';
      console.log(`${icon} ${testFile.padEnd(45)} (${result.pattern})`);
    } catch (error) {
      console.log(`❌ ${testFile} (error: ${error.message})`);
    }
  });

  console.log(`\n✅ Refactored tests with smart patterns:`);
  console.log(`   📦 Class-based: ${stats.class}`);
  console.log(`   ⚙️  Function-based: ${stats.functions + stats['named-exports']}`);
  console.log(`   ❓ Unknown: ${stats.unknown}`);
  console.log(`\n📊 Run: npm test to validate new test logic`);
}

if (require.main === module) {
  main();
}

module.exports = { detectExportPattern, extractExportedFunctions };
